import { Request, Response } from 'express';
import { SafeModeSmokeService } from './safe-mode-smoke.service';

export const SafeModeSmokeController = {
  async list(_req: Request, res: Response) {
    const data = await SafeModeSmokeService.list();
    return res.json(data);
  },

  async create(req: Request, res: Response) {
    const created = await SafeModeSmokeService.create(req.body);
    return res.status(201).json(created);
  },
};

import { SafeModeSmokeRepository } from './safe-mode-smoke.repository';

export const SafeModeSmokeService = {
  list() {
    return SafeModeSmokeRepository.list();
  },

  create(payload: { name: string; description?: string }) {
    return SafeModeSmokeRepository.create(payload);
  },
};

const memoryStore: Array<{ id: string; name: string; description?: string }> = [];

export const SafeModeSmokeRepository = {
  list() {
    return memoryStore;
  },

  create(payload: { name: string; description?: string }) {
    const item = { id: String(Date.now()), ...payload };
    memoryStore.unshift(item);
    return item;
  },
};

import { request } from '../services/http/request';

export function listSafeModeSmoke() {
  return request<Array<{ id: string; name: string }>>({ method: 'GET', url: '/safe-mode-smoke' });
}

export function createSafeModeSmoke(payload: { name: string; description?: string }) {
  return request<{ id: string; name: string }>({ method: 'POST', url: '/safe-mode-smoke', data: payload });
}

import { useEffect, useState } from 'react';
